export interface MediaItem {
  url: string
  type: 'image' | 'video'
}

export interface VolumeOption {
  volume: string
  price: string
  rawPrice: number
}

export interface Product {
  id: string
  name: string
  category: string
  type: string
  price: string
  rawPrice: number
  description: string
  image: string
  images?: string[]
  media?: MediaItem[]
  tag?: string
  contenance?: string
  volumes?: VolumeOption[]
  colors?: string[]
  color?: string
  rating: number
  reviewsCount: number
}

/**
 * Détecte de manière fiable si une URL (y compris data:video/ base64) est une vidéo
 */
export function isVideoUrl(url: unknown): boolean {
  if (!url || typeof url !== 'string') return false
  const trimmed = url.trim()
  if (trimmed.startsWith('data:video/')) return true
  return /\.(mp4|webm|mov|avi|m4v|ogg)(\?.*)?$/i.test(trimmed)
}

/**
 * Extrait les déclinaisons de contenance et leurs prix personnalisés
 */
export function extractVolumes(p?: {
  name?: string
  description?: string
  contenance?: string
  price?: string
  rawPrice?: number
  volumes?: VolumeOption[]
} | null): VolumeOption[] {
  if (!p) return []
  if (p.volumes && Array.isArray(p.volumes) && p.volumes.length > 0) {
    return p.volumes
  }

  let list: VolumeOption[] = []

  // 1. Tag HTML comment <!--VOLUMES_JSON_START-->...<!--VOLUMES_JSON_END-->
  const commentMatch = (p.description || '').match(/<!--VOLUMES_JSON_START-->([\s\S]*?)<!--VOLUMES_JSON_END-->/)
  if (commentMatch) {
    try {
      const parsed = JSON.parse(commentMatch[1].trim())
      if (Array.isArray(parsed) && parsed.length > 0) {
        list = parsed
      }
    } catch {}
  }

  // 2. Tag [VolumesJSON: [...]] dans la description
  if (list.length === 0) {
    const jsonMatch =
      (p.description || '').match(/\[VolumesJSON:\s*(\[\s*\{[\s\S]*?\}\s*\])\s*\]/i) ||
      (p.description || '').match(/\[VolumesJSON:\s*([\s\S]+?)\]\]/i)
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[1].trim())
        if (Array.isArray(parsed) && parsed.length > 0) {
          list = parsed
        }
      } catch {}
    }
  }

  // 3. Tag simple [Volumes: 30 ml:120, 50 ml:180, 100 ml:250]
  if (list.length === 0) {
    const simpleMatch = (p.description || '').match(/\[Volumes:\s*([^\]]+)\]/i)
    if (simpleMatch) {
      const parts = simpleMatch[1].split(/[|,]/)
      for (const part of parts) {
        const [vol, pr] = part.split(':')
        if (vol && pr) {
          const raw = parseFloat(pr.replace(/[^0-9.,]/g, '').replace(',', '.')) || 0
          const formatted = pr.includes('€') ? pr.trim() : `${raw.toFixed(2).replace('.', ',')} €`
          list.push({ volume: vol.trim(), price: formatted, rawPrice: raw })
        }
      }
    }
  }

  // Si on a des déclinaisons partielles et qu'une contenance principale existe (ex: 100 ml)
  // non incluse dans la liste, on l'ajoute avec le prix principal du produit
  const mainCont = p.contenance?.trim() || ''
  if (list.length > 0 && mainCont && p.price) {
    const alreadyPresent = list.some(
      (v) => v.volume.toLowerCase().replace(/\s/g, '') === mainCont.toLowerCase().replace(/\s/g, '')
    )
    if (!alreadyPresent && /(\d+)\s*(ml|g|cl|oz)/i.test(mainCont)) {
      list.push({
        volume: mainCont,
        price: p.price,
        rawPrice: p.rawPrice || 0,
      })
    }
  }

  // Trier par volume croissant si numérique
  if (list.length > 1) {
    list.sort((a, b) => {
      const numA = parseInt(a.volume.replace(/\D/g, ''), 10) || 0
      const numB = parseInt(b.volume.replace(/\D/g, ''), 10) || 0
      return numA - numB
    })
  }

  return list
}

/**
 * Extrait intelligemment la contenance d'un produit :
 * 1. Depuis le champ explicite contenance
 * 2. Depuis les variantes de volumes
 * 3. Depuis un marqueur [Contenance: ...] dans la description
 * 4. Depuis le nom du produit (ex: "50 ml", "100 ml", "30ml", "200 ml")
 * 5. Depuis le type ou la description
 */
export function extractContenance(p?: {
  name?: string
  description?: string
  type?: string
  contenance?: string
  volumes?: VolumeOption[]
} | null): string {
  if (!p) return ''
  if (p.contenance && p.contenance.trim()) return p.contenance.trim()

  // Si des variantes de volumes existent, renvoyer la liste séparée par des virgules
  const vols = extractVolumes(p)
  if (vols.length > 0) {
    return vols.map((v) => v.volume).join(', ')
  }

  // 1. Marqueur dans la description
  const markerMatch = (p.description || '').match(/\[Contenance:\s*([^\]]+)\]/i)
  if (markerMatch) return markerMatch[1].trim()

  // 2. Recherche dans le nom (ex: "50 ml", "100 ml", "30ml", "200 ml")
  const nameMatch = (p.name || '').match(/(\d+[\s]*(?:ml|g|cl|oz))\b/i)
  if (nameMatch) {
    return nameMatch[1].replace(/(\d+)\s*(ml|g|cl|oz)/i, '$1 $2').toLowerCase()
  }

  // 3. Recherche dans le type
  const typeMatch = (p.type || '').match(/(\d+[\s]*(?:ml|g|cl|oz))\b/i)
  if (typeMatch) {
    return typeMatch[1].replace(/(\d+)\s*(ml|g|cl|oz)/i, '$1 $2').toLowerCase()
  }

  // 4. Recherche dans la description
  const descMatch = (p.description || '').match(/(\d+[\s]*(?:ml|g|cl|oz))\b/i)
  if (descMatch) {
    return descMatch[1].replace(/(\d+)\s*(ml|g|cl|oz)/i, '$1 $2').toLowerCase()
  }

  return ''
}

export function getCleanDescription(desc: string = ''): string {
  return desc
    .replace(/<!--VOLUMES_JSON_START-->[\s\S]*?<!--VOLUMES_JSON_END-->/g, '')
    .replace(/<!--COLORS_JSON_START-->[\s\S]*?<!--COLORS_JSON_END-->/g, '')
    .replace(/\n*\[Contenance:[^\]]+\]/gi, '')
    .replace(/\n*\[(?:Couleurs?|Colors?):[^\]]+\]/gi, '')
    .replace(/\n*\[Volumes(?:JSON)?:\s*\[[\s\S]*?\]\]/gi, '')
    .replace(/\n*\[Volumes:[^\]]+\]/gi, '')
    .replace(/\n*\[VolumesJSON:[^\]]+\]/gi, '')
    .trim()
}

/**
 * Retourne la description nettoyée de toute syntaxe image pour affichage condensé (cartes, badges)
 */
export function stripImagesFromDescription(desc?: string): string {
  if (!desc) return ''
  return getCleanDescription(desc)
    .replace(/!\[(.*?)\]\(.*?\)/g, '')
    .replace(/<img[^>]*>/gi, '')
    .trim()
}

export const COMMON_COLORS: { name: string; hex: string }[] = [
  { name: 'Noir', hex: '#1c1c1c' },
  { name: 'Blanc', hex: '#ffffff' },
  { name: 'Doré / Or', hex: '#d4af37' },
  { name: 'Argent', hex: '#c0c0c0' },
  { name: 'Beige / Nude', hex: '#e8dcce' },
  { name: 'Rose Poudré', hex: '#f3c5c5' },
  { name: 'Rouge Écarlate', hex: '#b91c1c' },
  { name: 'Bordeaux', hex: '#7f1d1d' },
  { name: 'Bleu Nuit', hex: '#1e3a8a' },
  { name: 'Vert Émeraude', hex: '#065f46' },
  { name: 'Marron / Cuir', hex: '#78350f' },
  { name: 'Gris Anthracite', hex: '#4b5563' },
  { name: 'Bronze', hex: '#cd7f32' },
  { name: 'Terracotta', hex: '#c86446' },
]

export function getColorHex(colorName: string): string {
  if (!colorName) return '#cccccc'
  const trimmed = colorName.trim()
  if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(trimmed)) return trimmed

  const hexMatch = trimmed.match(/#([0-9a-f]{6}|[0-9a-f]{3})\b/i)
  if (hexMatch) return hexMatch[0]

  const lower = trimmed.toLowerCase()
  for (const c of COMMON_COLORS) {
    if (lower === c.name.toLowerCase() || c.name.toLowerCase().includes(lower) || lower.includes(c.name.toLowerCase().split(' ')[0])) {
      return c.hex
    }
  }

  if (lower.includes('noir') || lower.includes('black')) return '#1c1c1c'
  if (lower.includes('blanc') || lower.includes('white')) return '#ffffff'
  if (lower.includes('or') || lower.includes('gold') || lower.includes('dor')) return '#d4af37'
  if (lower.includes('argent') || lower.includes('silver')) return '#c0c0c0'
  if (lower.includes('rose') || lower.includes('pink')) return '#f472b6'
  if (lower.includes('rouge') || lower.includes('red')) return '#dc2626'
  if (lower.includes('bleu') || lower.includes('blue')) return '#2563eb'
  if (lower.includes('vert') || lower.includes('green')) return '#16a34a'
  if (lower.includes('beige') || lower.includes('nude') || lower.includes('creme') || lower.includes('crème')) return '#e8dcce'
  if (lower.includes('marron') || lower.includes('brown') || lower.includes('cuir')) return '#78350f'
  if (lower.includes('gris') || lower.includes('grey') || lower.includes('gray')) return '#6b7280'
  if (lower.includes('violet') || lower.includes('purple')) return '#7c3aed'
  if (lower.includes('jaune') || lower.includes('yellow')) return '#facc15'
  if (lower.includes('orange')) return '#ea580c'

  return '#b8c8a6'
}

export function extractColors(p?: {
  colors?: string[]
  color?: string
  description?: string
} | null): string[] {
  if (!p) return []
  if (p.colors && Array.isArray(p.colors) && p.colors.length > 0) {
    return p.colors.map((c) => String(c).trim()).filter(Boolean)
  }
  if (p.color && typeof p.color === 'string' && p.color.trim()) {
    return p.color.split(',').map((c) => c.trim()).filter(Boolean)
  }

  const commentMatch = (p.description || '').match(/<!--COLORS_JSON_START-->([\s\S]*?)<!--COLORS_JSON_END-->/)
  if (commentMatch) {
    try {
      const parsed = JSON.parse(commentMatch[1].trim())
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed.map((c: any) => String(c).trim()).filter(Boolean)
      }
    } catch {}
  }

  const markerMatch = (p.description || '').match(/\[(?:Couleurs?|Colors?):\s*([^\]]+)\]/i)
  if (markerMatch) {
    return markerMatch[1].split(',').map((c) => c.trim()).filter(Boolean)
  }

  return []
}

